    {
        RuleFor(x => x.Name)
            .NotEmpty().WithMessage("name_required")
            .MaximumLength(100).WithMessage("name_too_long")
            .Matches("^[a-zA-Z0-9_-]+$").WithMessage("name_invalid_format");

        RuleFor(x => x.Description)
            .MaximumLength(200).WithMessage("description_too_long");
    }
}

// Updated endpoint
RequireAdmin(app.MapPost("/admin/scopes", async (AuthDbContext db, CreateScopeRequest input, IValidator<CreateScopeRequest> validator) =>
{
    var validationResult = await validator.ValidateAsync(input);
    if (!validationResult.IsValid)
    {
