using Microsoft.EntityFrameworkCore.Diagnostics;

public sealed class EmailNormalizationInterceptor : SaveChangesInterceptor
{
    public override ValueTask<InterceptionResult<int>> SavingChangesAsync(
        DbContextEventData eventData,
        InterceptionResult<int> result,
        CancellationToken cancellationToken = default)
    {
        var dbContext = eventData.Context;
        if (dbContext is null) return base.SavingChangesAsync(eventData, result, cancellationToken);

        var entries = dbContext.ChangeTracker.Entries<User>()
            .Where(e => e.State == EntityState.Added || e.State == EntityState.Modified);

        foreach (var entry in entries)
        {
            if (!string.IsNullOrWhiteSpace(entry.Entity.Email))
            {
                entry.Entity.Email = entry.Entity.Email.Trim().ToLowerInvariant();
            }
        }

        return base.SavingChangesAsync(eventData, result, cancellationToken);
    }
}

// MrWhoOidc.Auth/Persistence/Interceptors/GuidCollisionInterceptor.cs
public sealed class GuidCollisionInterceptor : SaveChangesInterceptor
{
    public override ValueTask<InterceptionResult<int>> SavingChangesAsync(
        DbContextEventData eventData,
        InterceptionResult<int> result,
        CancellationToken cancellationToken = default)
    {
        var dbContext = eventData.Context;
        if (dbContext is null) return base.SavingChangesAsync(eventData, result, cancellationToken);

        // Handle GUID collision resolution for entities that need it
        var entries = dbContext.ChangeTracker.Entries()
            .Where(e => e.State == EntityState.Added);

        foreach (var entry in entries)
        {
            if (entry.Entity is IHasGuidId idEntity && idEntity.Id == Guid.Empty)
            {
                idEntity.Id = Guid.NewGuid();
            }
        }

        return base.SavingChangesAsync(eventData, result, cancellationToken);
    }
}

// Register interceptors in Program.cs
builder.Services.AddDbContext<AuthDbContext>((sp, options) =>
{
    var configuration = sp.GetRequiredService<IConfiguration>();
    var connectionString = configuration.GetConnectionString("DefaultConnection");

    options.UseNpgsql(connectionString)
           .AddInterceptors(
               sp.GetRequiredService<EmailNormalizationInterceptor>(),
               sp.GetRequiredService<GuidCollisionInterceptor>());
});

// Register interceptors as services
builder.Services.AddScoped<EmailNormalizationInterceptor>();
builder.Services.AddScoped<GuidCollisionInterceptor>();


