// Use database-level constraints or optimistic concurrency
public async Task SetPrimarySecretAsync(Guid clientId, Guid secretId, CancellationToken ct = default)
{
    using var transaction = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct);
    try
    {
        // Clear all primary flags for this client
        await db.ClientSecrets
            .Where(s => s.ClientId == clientId && s.IsPrimary)
            .ExecuteUpdateAsync(s => s.SetProperty(x => x.IsPrimary, false), ct);

        // Set new primary
        var secret = await db.ClientSecrets
            .FirstOrDefaultAsync(s => s.Id == secretId && s.ClientId == clientId, ct);

        if (secret is null)
        {
            await transaction.RollbackAsync(ct);
            throw new NotFoundException("Client secret not found");
        }

        secret.IsPrimary = true;
        await db.SaveChangesAsync(ct);
        await transaction.CommitAsync(ct);
    }
    catch
    {
        await transaction.RollbackAsync(ct);
        throw;
    }
}


