using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;

public static class ScopeEndpoints
{
    public static IEndpointRouteBuilder MapScopeEndpoints(this IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/admin/scopes").WithTags("Scopes");

        group.MapGet("/", async (AuthDbContext db, int? skip, int? take) =>
        {
            IQueryable<Scope> q = db.Scopes.AsNoTracking().OrderBy(s => s.Name);
            if (skip is > 0) q = q.Skip(skip.Value);
            if (take is > 0 && take.Value <= 200) q = q.Take(take.Value);
            var list = await q.ToListAsync();
            return Results.Ok(list);
        })
        .RequireAuthorization("admin")
        .WithName("GetScopes")
        .WithSummary("Get all scopes")
        .WithOpenApi();

        group.MapPost("/", async (AuthDbContext db, CreateScopeRequest input, IValidator<CreateScopeRequest> validator) =>
        {
            var validationResult = await validator.ValidateAsync(input);
            if (!validationResult.IsValid)
            {
                return Results.BadRequest(new { error = validationResult.Errors.First().ErrorCode });
            }

            var exists = await db.Scopes.AnyAsync(s => s.Name == input.Name);
            if (exists) return Results.Conflict(new { error = "scope_exists" });

            db.Scopes.Add(new Scope { Name = input.Name, Description = input.Description, IsExposed = input.IsExposed });
            await db.SaveChangesAsync();
            return Results.Created($"/admin/scopes/{input.Name}", input);
        })
        .RequireAuthorization("admin")
        .WithName("CreateScope")
        .WithSummary("Create a new scope")
        .WithOpenApi();

        group.MapPut("/{name}", async (AuthDbContext db, string name, UpdateScopeRequest input, IValidator<UpdateScopeRequest> validator) =>
        {
            var validationResult = await validator.ValidateAsync(input);
            if (!validationResult.IsValid)
            {
                return Results.BadRequest(new { error = validationResult.Errors.First().ErrorCode });
            }

            var entity = await db.Scopes.FirstOrDefaultAsync(s => s.Name == name);
            if (entity is null) return Results.NotFound();

            entity.Description = input.Description;
            entity.IsExposed = input.IsExposed;
            await db.SaveChangesAsync();
            return Results.NoContent();
        })
        .RequireAuthorization("admin")
        .WithName("UpdateScope")
        .WithSummary("Update a scope")
        .WithOpenApi();

        group.MapDelete("/{name}", async (AuthDbContext db, string name) =>
        {
            var inUse = await db.ClientScopes.AnyAsync(cs => cs.ScopeName == name);
            if (inUse) return Results.Conflict(new { error = "scope_in_use" });

            var entity = await db.Scopes.FirstOrDefaultAsync(s => s.Name == name);
            if (entity is null) return Results.NotFound();

            db.Remove(entity);
            await db.SaveChangesAsync();
            return Results.NoContent();
        })
        .RequireAuthorization("admin")
        .WithName("DeleteScope")
        .WithSummary("Delete a scope")
        .WithOpenApi();

        return app;
    }
}

