        IValidator<T> validator)
    {
        var validationResult = await validator.ValidateAsync(request);
        if (!validationResult.IsValid)
        {
            return Results.BadRequest(new { error = validationResult.Errors.First().ErrorCode });
        }
        return Results.Ok(request);
    }

    public static async Task<IResult> HandleConflictAsync<T>(
        Func<Task<bool>> existsCheck,
        string errorCode)
    {
        if (await existsCheck())
        {
            return Results.Conflict(new { error = errorCode });
        }
        return Results.Ok();
    }
}

// Use in endpoints
RequireAdmin(app.MapPost("/admin/scopes", async (
    AuthDbContext db, 
    CreateScopeRequest input, 
    IValidator<CreateScopeRequest> validator) =>
{
    var validationResult = await validator.ValidateAsync(input);
    if (!validationResult.IsValid)
    {
        return Results.BadRequest(new { error = validationResult.Errors.First().ErrorCode });
    }

    var exists = await db.Scopes.AnyAsync(s => s.Name == input.Name);
    if (exists) return Results.Conflict(new { error = "scope_exists" });

    db.Scopes.Add(new Scope { Name = input.Name, Description = input.Description, IsExposed = input.IsExposed });
    await db.SaveChangesAsync();
    return Results.Created($"/admin/scopes/{input.Name}", input);
}));


