            error_description = $"Client 'id_token_signed_response_alg' '{client.IdTokenSignedResponseAlg}' must match tenant active signing alg '{signingAlg}'."
        },
        OAuthConstants.ErrorCodes.InvalidRequest,
        400);
}


**Impact**: Attackers can enumerate client configurations, discover supported algorithms, and gain insight into tenant settings.

#### Fix Implementation

csharp
// FIXED CODE - Generic errors with server-side logging
