            .NotEmpty().WithMessage("client_id_required")
            .MaximumLength(100).WithMessage("client_id_too_long");

        RuleFor(x => x.ClientSecret)
            .MaximumLength(200).WithMessage("client_secret_too_long")
            .When(x => !string.IsNullOrEmpty(x.ClientSecret));
