}

// Updated endpoint with proper secret handling
RequireAdmin(app.MapPost("/admin/clients", async (AuthDbContext db, CreateClientRequest input, IValidator<CreateClientRequest> validator) =>
{
    var validationResult = await validator.ValidateAsync(input);
    if (!validationResult.IsValid)
    {
        return Results.BadRequest(new { error = validationResult.Errors.First().ErrorCode });
    }

    var clientId = input.ClientId.Trim();
    var exists = await db.Clients.AnyAsync(c => c.ClientId == clientId);
