// MrWhoOidc.Auth/Services/IClientUsageService.cs
namespace MrWhoOidc.Auth.Services;

public interface IClientUsageService
{
    Task<bool> IsClientInUseAsync(Guid clientId, CancellationToken ct = default);
}

// MrWhoOidc.Auth/Services/ClientUsageService.cs
using Microsoft.EntityFrameworkCore;
using MrWhoOidc.Auth.Persistence;

internal sealed class ClientUsageService(AuthDbContext db) : IClientUsageService
{
    public async Task<bool> IsClientInUseAsync(Guid clientId, CancellationToken ct = default)
    {
        var clientIdStr = clientId.ToString();

        return await db.AuthorizationCodes.AnyAsync(c => c.ClientId == clientIdStr, ct)
            || await db.Consents.AnyAsync(c => c.ClientId == clientIdStr, ct)
            || await db.Tokens.AnyAsync(t => t.ClientId == clientIdStr, ct)
            || await db.UserClientAssignments.AnyAsync(a => a.ClientId == clientId, ct)
            || await db.UserClientRoleAssignments.AnyAsync(a => a.ClientId == clientId, ct);
    }
}

// Register in DI
// MrWhoOidc.Auth/ServiceCollectionExtensions.cs
builder.Services.AddScoped<IClientUsageService, ClientUsageService>();

// Updated API endpoint
RequireAdmin(app.MapDelete("/admin/clients/{id:guid}", async (AuthDbContext db, IClientUsageService usageService, Guid id) =>
{
