// MrWhoOidc.Auth/Services/KeyRotationService.cs
using Microsoft.Extensions.Hosting;
using Polly;
using Polly.Retry;

public sealed class KeyRotationService(
    IKeyStore keyStore,
    IOptions<KeyRotationOptions> options,
    ILogger<KeyRotationService> logger) : BackgroundService
{
    private readonly AsyncRetryPolicy _retryPolicy = Policy
        .Handle<Exception>()
        .WaitAndRetryAsync(
            retryCount: 3,
            sleepDurationProvider: retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)),
            onRetry: (exception, timeSpan, retryCount, context) =>
            {
                logger.LogWarning(exception, 
                    "Key rotation attempt {RetryCount} failed after {Delay}s. Retrying...", 
                    retryCount, timeSpan.TotalSeconds);
            });

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                await _retryPolicy.ExecuteAsync(async () =>
                {
                    logger.LogInformation("Starting key rotation check");

                    // Check if rotation is needed
                    var activeKey = await keyStore.GetActiveSigningKeyAsync(stoppingToken);
                    var keyAge = DateTimeOffset.UtcNow - activeKey.KeyId; // Assuming CreatedAt is available

                    if (keyAge > options.Value.RotationInterval)
                    {
                        logger.LogInformation("Key rotation required. Active key age: {Age}", keyAge);

                        // Generate new key
                        await keyStore.InvalidateActiveSigningKeyCacheAsync(
                            options.Value.TenantId, stoppingToken);

                        // Force new key generation
                        var newKey = await keyStore.GetActiveSigningKeyAsync(stoppingToken);

                        logger.LogInformation("Key rotation completed. New key: {Kid}", newKey.Kid);
                    }
                });
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Key rotation failed after all retries");
            }

            await Task.Delay(TimeSpan.FromHours(1), stoppingToken);
        }
    }
}


