public sealed class TenantQueryFilterInterceptor(ITenantAccessor tenantAccessor) : SaveChangesInterceptor
{
    public override InterceptionResult<int> SavingChanges(
        DbContextEventData eventData,
        InterceptionResult<int> result)
    {
        var dbContext = eventData.Context;
        if (dbContext is null) return base.SavingChanges(eventData, result);

        var tenantId = tenantAccessor.CurrentTenant?.TenantId;
        if (tenantId is null) return base.SavingChanges(eventData, result);

        // Automatically set tenant ID for tenant-scoped entities
        var entries = dbContext.ChangeTracker.Entries<ITenantScoped>()
            .Where(e => e.State == EntityState.Added);

        foreach (var entry in entries)
        {
            if (entry.Entity.TenantId == Guid.Empty)
            {
                entry.Entity.TenantId = tenantId.Value;
            }
        }

        return base.SavingChanges(eventData, result);
    }
}

