### QUAL-005: Extract Smaller, Focused Methods
**Severity**: Minor (2)  

#### Fix Implementation

csharp
// MrWhoOidc.Auth/Services/Token/AuthorizationCodeExchanger.cs
// Extract large method into smaller methods
public sealed class AuthorizationCodeExchanger(
    AuthDbContext db,
    IJwtService jwt,
    ICachedKeyProvider keyProvider,
    IRefreshTokenService refreshTokens,
    IRevocationService revocations,
    IOptions<AuthOptions> authOptions,
    IAuthorizationCodeMetadataStore meta,
    ITenantSettingsService settingsService,
    IEntitlementsProvider entitlementsProvider,
    ITenantsClaimService tenantsClaimService,
    IPairwiseSubjectService pairwiseSubjectService,
    IAccessTokenClaimBuilder claimBuilder,
    ITokenLifetimeResolver lifetimeResolver,
    IOpaqueTokenPolicy opaquePolicy,
    ILogger<AuthorizationCodeExchanger> logger) : IAuthorizationCodeExchanger
{
    public async Task<(bool ok, object? payload, string? error, int status)> ExchangeAsync(
        AuthorizationCodeExchangeRequest request, 
        CancellationToken ct = default)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        return await strategy.ExecuteAsync<(bool ok, object? payload, string? error, int status)>(async () =>
        {
            using var transaction = await db.Database.BeginTransactionAsync(ct).ConfigureAwait(false);
            try
            {
                // Validate authorization code
                var validationResult = await ValidateAuthorizationCodeAsync(request, ct);
                if (!validationResult.IsValid)
                {
                    return validationResult.ErrorResult;
                }

                // Build access token
                var accessTokenResult = await BuildAccessTokenAsync(request, validationResult.Entity, ct);

                // Build ID token
                var idTokenResult = await BuildIdTokenAsync(request, validationResult.Entity, accessTokenResult, ct);

                // Create refresh token
                var refreshToken = await refreshTokens.CreateRefreshTokenAsync(
                    validationResult.Entity.UserId, 
                    request.ClientId, 
                    validationResult.Scopes, 
                    request.IpAddress, 
                    request.UserAgent, 
                    ct).ConfigureAwait(false);

                // Mark code as consumed
                validationResult.Entity.Consumed = true;
                await db.SaveChangesAsync(ct).ConfigureAwait(false);
                await transaction.CommitAsync(ct).ConfigureAwait(false);

                meta.Remove(request.Code);

                var payload = new
                {
                    access_token = accessTokenResult.Token,
                    id_token = idTokenResult.Token,
                    refresh_token = refreshToken,
                    token_type = OAuthConstants.TokenTypes.Bearer,
                    expires_in = (int)accessTokenResult.Lifetime.TotalSeconds,
                    scope = string.Join(' ', validationResult.Scopes)
                };
                return (true, payload, null, 200);
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Error during authorization code exchange");
                throw;
            }
        });
    }

    private async Task<AuthorizationCodeValidationResult> ValidateAuthorizationCodeAsync(
        AuthorizationCodeExchangeRequest request, 
        CancellationToken ct)
    {
        var entity = await db.AuthorizationCodes.FirstOrDefaultAsync(c => c.Code == request.Code, ct).ConfigureAwait(false);
        if (entity is null || entity.Consumed || entity.ExpiresAt < DateTimeOffset.UtcNow)
        {
            if (entity is not null && entity.Consumed)
            {
                await revocations.RevokeAllForUserAsync(entity.UserId, entity.ClientId, ct).ConfigureAwait(false);
            }
            return new AuthorizationCodeValidationResult
            {
                IsValid = false,
                ErrorResult = (false, new { error = OAuthConstants.ErrorCodes.InvalidGrant }, OAuthConstants.ErrorCodes.InvalidGrant, 400)
            };
        }

        if (!string.Equals(entity.RedirectUri, request.RedirectUri, StringComparison.Ordinal))
            return new AuthorizationCodeValidationResult
            {
                IsValid = false,
                ErrorResult = (false, new { error = OAuthConstants.ErrorCodes.InvalidGrant }, OAuthConstants.ErrorCodes.InvalidGrant, 400)
            };

        if (!string.Equals(entity.ClientId, request.ClientId, StringComparison.Ordinal))
            return new AuthorizationCodeValidationResult
            {
                IsValid = false,
                ErrorResult = (false, new { error = OAuthConstants.ErrorCodes.InvalidGrant }, OAuthConstants.ErrorCodes.InvalidGrant, 400)
            };

        // Validate PKCE
        if (!string.IsNullOrEmpty(entity.CodeChallenge))
        {
            var s256 = CryptoHelper.ComputePkceS256(request.CodeVerifier);
            if (!string.Equals(s256, entity.CodeChallenge, StringComparison.Ordinal))
                return new AuthorizationCodeValidationResult
                {
                    IsValid = false,
                    ErrorResult = (false, new { error = OAuthConstants.ErrorCodes.InvalidGrant }, OAuthConstants.ErrorCodes.InvalidGrant, 400)
                };
        }

        var scopes = JsonSerializer.Deserialize<string[]>(entity.ScopesJson) ?? Array.Empty<string>();
        return new AuthorizationCodeValidationResult
        {
            IsValid = true,
            Entity = entity,
            Scopes = scopes
        };
    }

    // ... other extracted methods ...
}

private record AuthorizationCodeValidationResult
{
    public bool IsValid { get; init; }
    public Persistence.AuthorizationCode? Entity { get; init; }
    public string[] Scopes { get; init; } = Array.Empty<string>();
    public (bool ok, object? payload, string? error, int status) ErrorResult { get; init; }
}


